function decodeEntities(s) {
  return s
    .replace(/&nbsp;/gi, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/&lt;/gi, '<')
    .replace(/&gt;/gi, '>')
    .replace(/&quot;/gi, '"')
    .replace(/&#39;/gi, "'")
    .replace(/&apos;/gi, "'")
    .replace(/&#x([0-9a-f]+);/gi, (_, h) => String.fromCharCode(parseInt(h, 16)))
    .replace(/#(\d+);/g, (_, d) => String.fromCharCode(parseInt(d, 10)));
}

function htmlToText(html) {
  if (!html) return '';
  let s = String(html);
  s = s.replace(/<script[\s\S]*?<\/script>/gi, '');
  s = s.replace(/<style[\s\S]*?<\/style>/gi, '');
  s = s.replace(/<!--[\s\S]*?-->/g, '');
  s = s.replace(/<head[\s\S]*?<\/head>/gi, '');
  s = s.replace(/<\/td\s*>/gi, '\t');
  s = s.replace(/<\/th\s*>/gi, '\t');
  s = s.replace(/<\/tr\s*>/gi, '\n');
  s = s.replace(/<br\s*\/?>/gi, '\n');
  s = s.replace(/<\/p\s*>/gi, '\n');
  s = s.replace(/<\/div\s*>/gi, '\n');
  s = s.replace(/<\/h[1-6]\s*>/gi, '\n');
  s = s.replace(/<\/li\s*>/gi, '\n');
  s = s.replace(/<[^>]+>/g, ' ');
  s = decodeEntities(s);
  s = s.split('\n')
    .map(line => line.replace(/[ \t\f\v]+/g, ' ').trim())
    .filter(line => line.length > 0)
    .join('\n');
  return s.substring(0, 12000);
}

const results = [];
for (const item of items) {
  const json = item.json || {};
  const bodyContent = (json.body && json.body.content) ? json.body.content : '';
  const isHtml = (json.body && json.body.contentType === 'html');
  const invoiceText = isHtml ? htmlToText(bodyContent) : String(bodyContent || '').substring(0, 12000);

  let emailFrom = '';
  if (json.from && json.from.emailAddress) {
    emailFrom = (json.from.emailAddress.name || '') + ' <' + (json.from.emailAddress.address || '') + '>';
  } else if (typeof json.from === 'string') {
    emailFrom = json.from;
  }

  results.push({
    json: {
      invoiceContent: invoiceText,
      emailSubject: json.subject || '',
      emailFrom: emailFrom,
      emailDate: json.receivedDateTime || '',
      emailUid: json.id || '',
      hasAttachment: Object.keys(item.binary || {}).length > 0
    },
    binary: item.binary
  });
}

return results;

function parseInvoiceJson(raw) {
  let cleaned = String(raw || '').trim()
    .replace(/^```json\s*/i, '')
    .replace(/^```\s*/i, '')
    .replace(/\s*```$/i, '')
    .trim();
  let parsed = {};
  try {
    const tmp = JSON.parse(cleaned);
    if (tmp && typeof tmp === 'object' && !Array.isArray(tmp)) parsed = tmp;
  } catch(e) {
    const m = cleaned.match(/\{[\s\S]*\}/);
    if (m) {
      try {
        const tmp2 = JSON.parse(m[0]);
        if (tmp2 && typeof tmp2 === 'object' && !Array.isArray(tmp2)) parsed = tmp2;
      } catch(e2) {}
    }
  }
  return parsed;
}

const fields = ['invoiceNumber','poNumber','vendorName','contactInfo','issueDate','dueDate',
  'subtotal','taxAmount','totalAmountDue','currency','paymentTerms','description',
  'quantityHours','unitPrice'];

const out = [];
for (let i = 0; i < items.length; i++) {
  const parsed = parseInvoiceJson(items[i].json.text);
  const row = {};
  for (const f of fields) {
    const v = parsed[f];
    row[f] = (v !== null && v !== undefined) ? String(v) : '';
  }
  let meta = {};
  try {
    meta = $('Code — Prepare Invoice Text').itemMatching(i).json || {};
  } catch(e) { meta = {}; }
  row.emailSubject = meta.emailSubject || '';
  row.emailFrom = meta.emailFrom || '';
  row.emailDate = meta.emailDate || '';
  row.emailUid = meta.emailUid || '';
  row.hasAttachment = meta.hasAttachment || false;
  out.push({ json: row });
}

return out;

const results = [];
const trueItems = $('IF — Has Attachment?').all(0, 0); 

const today = new Date();
const pad = (n) => String(n).padStart(2, '0');
const folderName = today.getFullYear() + '-' + pad(today.getMonth() + 1) + '-' + pad(today.getDate());
const baseFolder = 'Invoices';
const folderPath = baseFolder + '/' + folderName;

for (let i = 0; i < items.length; i++) {
  const attachData = items[i].json;
  const row = trueItems[i] ? trueItems[i].json : {};

  let vendorSlug = String(row.vendorNameRaw || 'UNKNOWN')
    .toUpperCase()
    .replace(/[^A-Z0-9]/g, '-')
    .replace(/-+/g, '-')
    .replace(/^-|-$/g, '')
    .substring(0, 30);
  if (!vendorSlug) vendorSlug = 'UNKNOWN';

  let monthStr = '';
  const issueRaw = String(row.issueDateRaw || '');
  const dateMatch = issueRaw.match(/(\d{4})-(\d{2})/);
  if (dateMatch) {
    monthStr = dateMatch[1] + '-' + dateMatch[2];
  } else {
    monthStr = today.getFullYear() + '-' + pad(today.getMonth() + 1);
  }

  const fileName = vendorSlug + '-' + monthStr + '.pdf';

  const attachments = attachData.value || [];
  let pdfBase64 = null;
  let pdfFound = false;
  for (const att of attachments) {
    const name = String(att.name || '').toLowerCase();
    const ctype = String(att.contentType || '').toLowerCase();
    if (name.endsWith('.pdf') || ctype.includes('pdf')) {
      pdfBase64 = att.contentBytes || null;
      pdfFound = true;
      break;
    }
  }

  if (!pdfFound && attachments.length > 0) {
    pdfBase64 = attachments[0].contentBytes || null;
    pdfFound = !!pdfBase64;
  }

  results.push({
    json: {
      folderName: folderName,
      folderPath: folderPath,
      fileName: fileName,
      pdfBase64: pdfBase64,
      pdfFound: pdfFound,
      uploadPath: folderPath + '/' + fileName,
      ...row
    }
  });
}

return results;

const results = [];
const uploadItems = $('Code — Build Upload Path').all();

for (let i = 0; i < items.length; i++) {
  const uploadData = uploadItems[i] ? uploadItems[i].json : items[i].json;
  const pdfBase64 = uploadData.pdfBase64 || '';

  if (!pdfBase64) {
    const emptyBinary = await this.helpers.prepareBinaryData(
      Buffer.from(''), 'blank.pdf', 'application/pdf'
    );
    results.push({
      json: { ...uploadData, pdfBinaryReady: false },
      binary: { pdfFile: emptyBinary }
    });
    continue;
  }

  const binaryData = await this.helpers.prepareBinaryData(
    Buffer.from(pdfBase64, 'base64'),
    uploadData.fileName,
    'application/pdf'
  );

  results.push({
    json: { ...uploadData, pdfBinaryReady: true },
    binary: { pdfFile: binaryData }
  });
}

return results;

const results = [];
const rowItems = $('Code — Build Upload Path').all();

for (let i = 0; i < items.length; i++) {
  const uploadResponse = items[i].json;
  const rowData = rowItems[i] ? rowItems[i].json : {};

  const pdfWebUrl = uploadResponse.webUrl || uploadResponse['@microsoft.graph.downloadUrl'] || '';

  const { folderName, folderPath, fileName, pdfBase64, pdfFound, uploadPath, pdfBinaryReady, vendorNameRaw, issueDateRaw, hasAttachment, ...cleanRow } = rowData;

  results.push({
    json: {
      ...cleanRow,
      pdfLink: pdfWebUrl
    }
  });
}

return results;

// No attachment — pass through all items with empty pdfLink
return items.map(item => {
  const { hasAttachment, vendorNameRaw, issueDateRaw, ...cleanRow } = item.json;
  return { json: { ...cleanRow, pdfLink: '' } };
});

const today = new Date().toLocaleDateString('en-US', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' });
const count = items.length;

// === CONFIGURATION ===
// Paste the direct link to your main OneDrive "Invoices" folder between the quotes below:
const oneDriveFolderUrl = 'YOUR_ONEDRIVE_FOLDER_URL'; 
// =====================

if (count === 0) {
  return [{ json: {
    subject: 'Invoice Digest - ' + today + ' - No Invoices Found',
    body: '<p>No invoice emails were detected in this run (' + today + ').</p>'
  }}];
}

const esc = (s) => String(s == null ? '' : s)
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;');

const formattedRows = $('Set — Format Excel Row').all();

let rows = '';
for (const it of items) {
  const matchedRow = formattedRows.find(row => row.json['Email UID'] === it.json.id);
  const r = matchedRow ? matchedRow.json : it.json;

  const inv = r['Invoice Number'] || 'N/A';
  const vendor = r['Vendor / Client Name'] || 'N/A';
  const issue = r['Issue Date'] || 'N/A';
  const due = r['Due Date'] || 'N/A';
  const from = r['Source Email From'] || 'N/A';

  let total = 'N/A';
  if (r['Total Amount Due']) {
    const amount = parseFloat(String(r['Total Amount Due']).replace(/[^0-9.-]+/g, ''));
    const currencyCode = (r['Currency'] || 'USD').trim().toUpperCase();
    if (!isNaN(amount)) {
      try {
        total = new Intl.NumberFormat('en-US', { style: 'currency', currency: currencyCode }).format(amount);
      } catch (e) {
        total = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD' }).format(amount);
      }
    } else {
      total = r['Total Amount Due']; 
    }
  }

  rows +=
    '<tr>' +
    '<td style="padding:6px 8px;border:1px solid #ddd;">' + esc(inv) + '</td>' +
    '<td style="padding:6px 8px;border:1px solid #ddd;">' + esc(vendor) + '</td>' +
    '<td style="padding:6px 8px;border:1px solid #ddd;">' + esc(issue) + '</td>' +
    '<td style="padding:6px 8px;border:1px solid #ddd;">' + esc(due) + '</td>' +
    '<td style="padding:6px 8px;border:1px solid #ddd;text-align:right;">' + esc(total) + '</td>' +
    '<td style="padding:6px 8px;border:1px solid #ddd;font-size:12px;">' + esc(from) + '</td>' +
    '</tr>';
}

const body =
  '<!DOCTYPE html><html><body style="font-family:Arial,sans-serif;color:#222;">\n' +
  '<h2 style="color:#002657;">Invoice Digest - ' + today + '</h2>\n' +
  '<p><strong>' + count + ' invoice(s)</strong> were detected, extracted, and logged to OneDrive today.</p>\n' +
  '<table style="border-collapse:collapse;width:100%;font-size:13px;">\n' +
  '<thead><tr style="background:#002657;color:#fff;">\n' +
  '<th style="padding:8px;border:1px solid #ddd;">Invoice #</th>\n' +
  '<th style="padding:8px;border:1px solid #ddd;">Vendor / Client</th>\n' +
  '<th style="padding:8px;border:1px solid #ddd;">Issue Date</th>\n' +
  '<th style="padding:8px;border:1px solid #ddd;">Due Date</th>\n' +
  '<th style="padding:8px;border:1px solid #ddd;">Total Due</th>\n' +
  '<th style="padding:8px;border:1px solid #ddd;">Source Email</th>\n' +
  '</tr></thead>\n' +
  '<tbody>' + rows + '</tbody>\n' +
  '</table>\n' +
  '<div style="text-align: center; margin-top: 35px; margin-bottom: 25px;">\n' +
  '  <a href="' + oneDriveFolderUrl + '" style="background-color: #002657; color: #ffffff; padding: 12px 24px; text-decoration: none; border-radius: 6px; font-weight: bold; display: inline-block; font-size: 14px;">Open OneDrive Folder</a>\n' +
  '</div>\n' +
  '<p style="margin-top:20px;font-size:12px;color:#888;">Processed emails have been marked as read.</p>\n' +
  '</body></html>';

return [{ json: {
  subject: 'Invoice Digest - ' + today + ' - ' + count + ' Invoice(s) Logged',
  body: body
}}];
